#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;long long k;scanf("%d %lld",&n,&k);
vector<long long>a(n);for(int i=0;i<n;++i)scanf("%lld",&a[i]);
k%=n;
for(int i=0;i<n;++i){if(i)printf(" ");printf("%lld",a[(i+k)%n]);}
printf("\n");return 0;}

